CREATE TABLE IF NOT EXISTS branches (id SERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','purchasing','accounting','retail','packing')), password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_branches (user_id INTEGER REFERENCES users(id), branch_id INTEGER REFERENCES branches(id), PRIMARY KEY(user_id,branch_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,contact TEXT NOT NULL DEFAULT '',items TEXT NOT NULL DEFAULT '',terms TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),supplier_id INTEGER REFERENCES suppliers(id),cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(cost_cents>=0));
CREATE TABLE IF NOT EXISTS inventory (branch_id INTEGER REFERENCES branches(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>=0),reorder_level INTEGER NOT NULL CHECK(reorder_level>=0),PRIMARY KEY(branch_id,product_id));
CREATE TABLE IF NOT EXISTS sales (id SERIAL PRIMARY KEY,receipt TEXT UNIQUE,client_key TEXT NOT NULL UNIQUE,branch_id INTEGER NOT NULL REFERENCES branches(id),user_id INTEGER NOT NULL REFERENCES users(id),total_cents INTEGER NOT NULL CHECK(total_cents>=0),created_at TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'retail' CHECK(kind IN ('retail','wholesale')),offline_recorded_at TEXT);
CREATE TABLE IF NOT EXISTS sale_items (id SERIAL PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES sales(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),price_cents INTEGER NOT NULL CHECK(price_cents>=0),returned_quantity INTEGER NOT NULL DEFAULT 0 CHECK(returned_quantity>=0 AND returned_quantity<=quantity));
CREATE TABLE IF NOT EXISTS returns (id SERIAL PRIMARY KEY,sale_id INTEGER NOT NULL REFERENCES sales(id),user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN ('refund','defective')),amount_cents INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_orders (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),supplier_id INTEGER NOT NULL REFERENCES suppliers(id),created_by INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','received')),approved_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_items (order_id INTEGER REFERENCES purchase_orders(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),received_quantity INTEGER NOT NULL DEFAULT 0 CHECK(received_quantity>=0 AND received_quantity<=quantity),unit_cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(unit_cost_cents>=0),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS deliveries (id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES purchase_orders(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),damaged_quantity INTEGER NOT NULL CHECK(damaged_quantity>=0 AND damaged_quantity<=quantity),received_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id SERIAL PRIMARY KEY,name TEXT NOT NULL,branch_id INTEGER NOT NULL REFERENCES branches(id),daily_rate_cents INTEGER NOT NULL CHECK(daily_rate_cents>=0));
CREATE TABLE IF NOT EXISTS attendance (id SERIAL PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),work_date TEXT NOT NULL,time_in TEXT NOT NULL,time_out TEXT,source TEXT NOT NULL DEFAULT 'simulated-fingerprint',recorded_by INTEGER NOT NULL REFERENCES users(id),UNIQUE(employee_id,work_date));
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,reference TEXT NOT NULL,user_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_requests (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),source_branch INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','fulfilled')),requested_by INTEGER NOT NULL REFERENCES users(id),approved_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,CHECK(branch_id<>source_branch));
CREATE TABLE IF NOT EXISTS transfers (id SERIAL PRIMARY KEY,source_branch INTEGER NOT NULL REFERENCES branches(id),destination_branch INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),request_id INTEGER UNIQUE REFERENCES stock_requests(id),client_key TEXT UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,CHECK(source_branch<>destination_branch));
CREATE TABLE IF NOT EXISTS replenishment (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','ordered','resolved')),order_id INTEGER REFERENCES purchase_orders(id),created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS replenishment_open ON replenishment(branch_id,product_id) WHERE status='open';
CREATE TABLE IF NOT EXISTS payroll_records (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),employee_id INTEGER NOT NULL REFERENCES employees(id),employee_name TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,days INTEGER NOT NULL CHECK(days>=0 AND days<=31),daily_rate_cents INTEGER NOT NULL,gross_cents INTEGER NOT NULL,sss_cents INTEGER NOT NULL,philhealth_cents INTEGER NOT NULL,pagibig_cents INTEGER NOT NULL,advance_cents INTEGER NOT NULL,net_cents INTEGER NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(employee_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS customers (id SERIAL PRIMARY KEY,name TEXT NOT NULL,contact TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS wholesale_orders (id SERIAL PRIMARY KEY,branch_id INTEGER NOT NULL REFERENCES branches(id),customer_id INTEGER NOT NULL REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'quote' CHECK(status IN ('quote','accepted','fulfilled')),created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,total_cents INTEGER NOT NULL CHECK(total_cents>=0),sale_id INTEGER UNIQUE REFERENCES sales(id));
CREATE TABLE IF NOT EXISTS wholesale_items (order_id INTEGER REFERENCES wholesale_orders(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),price_cents INTEGER NOT NULL CHECK(price_cents>=0),PRIMARY KEY(order_id,product_id));
CREATE INDEX IF NOT EXISTS sales_branch_date ON sales(branch_id,created_at);
CREATE INDEX IF NOT EXISTS attendance_employee_date ON attendance(employee_id,work_date);
CREATE TABLE IF NOT EXISTS supplier_invoices (id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE REFERENCES purchase_orders(id),invoice_number TEXT NOT NULL UNIQUE,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),invoice_date TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
